{"command": "curl -s https://dotnetcli.blob.core.windows.net/dotnet/release-metadata/releases-index.json | python3 -c "
import json,sys
data=json.load(sys.stdin)
for r in data['releases-index']:
    if r['support-phase']=='active':
        print(f\"Active: .NET {r['channel-version']} — latest SDK: {r['latest-sdk']}\")
"", "description": "Find active .NET releases"}

